class Solution {
public:
    long long countTheNumOfKFreeSubsets(vector<int>& nums, int k) {
        map<int, int> freq;
        for (int x : nums) ++freq[x];
        set<int> visited;
        long long result = 1;
        for (const auto& item : freq) {
            int start = item.first;
            if (visited.count(start)) continue;
            if (freq.count(start - k)) continue;
            long long skip = 1, take = 0;
            for (int x = start; freq.count(x); x += k) {
                visited.insert(x);
                long long choices = (1LL << freq[x]) - 1;
                long long newSkip = skip + take;
                long long newTake = skip * choices;
                skip = newSkip;
                take = newTake;
            }
            result *= skip + take;
        }
        return result;
    }
};
